using EchoSphere.Core;
internal static class CampaignRegionChecks {
 internal static int Run(){int checks=0;void Check(bool value,string why){checks++;if(!value)throw new Exception("Campaign regions: "+why);}
 Check((int)EchoRegionId.ResonanceBasin==0&&(int)EchoRegionId.SpectralRift==1,"legacy enum values stable");var ids=new HashSet<string>();var validRoles=new HashSet<string>{"grunt","swarmer","tank_guard","ranged","sniper","healer","disruptor","charger","phase","leech","splitter","corruptor","scavenger","anchor","bomber"};var validBosses=new HashSet<string>{"shooter","charger","summoner","aura","conductor","architect","null","stella_warden"};
 for(int i=0;i<6;i++){var region=(EchoRegionId)i;string id=CampaignRegions.SourceId(region);Check(ids.Add(id),"unique save identity");Check(CampaignRegions.TryParse(id,out var parsed)&&parsed==region,"roundtrip identity");Check(CampaignRegions.IsUnlocked(region,_=>false)==(i==0),"locked chain");Check(CampaignRegions.IsUnlocked(region,previous=>(int)previous==i-1),"previous stabilization opens next");var state=RegionBossScheduleRules.Create(region);var bosses=new List<string>();int cleared=0;for(int time=0;time<=1800;time++){var signal=RegionBossScheduleRules.Advance(state,time,false);if(signal.Kind==RegionBossSignalKind.SpawnBoss){Check(validBosses.Contains(signal.BossType),"real boss handler");bosses.Add(signal.BossType);}if(signal.Kind==RegionBossSignalKind.RegionCleared)cleared++;}Check(bosses.Count==3&&cleared==1&&state.Cleared,"two major bosses,final boss,thirty minute completion");var copy=RegionBossScheduleRules.Create();RunSnapshotCodec.Restore(RunSnapshotCodec.Capture(state),typeof(RegionBossScheduleState),copy);Check(copy.RegionId==region&&copy.Cleared&&copy.MajorBossesSpawned==2,"boss schedule save roundtrip");Check(RegionBossScheduleRules.Advance(state,1900,false).Kind==RegionBossSignalKind.None,"no duplicate completion");}
 Check(!CampaignRegions.TryParse("not_a_region",out _),"invalid launch ID rejected");Check(!CampaignRegions.IsUnlocked((EchoRegionId)6,_=>true),"invalid enum locked");
 foreach(var profile in CampaignRegions.Additional){Check(profile.Pockets.Length==5,"five authored pockets");Check(new HashSet<string>{profile.FirstBoss,profile.SecondBoss,profile.FinalBoss}.Count==3,"three distinct scheduled boss families");var names=new HashSet<string>();var pools=new HashSet<string>();foreach(var pocket in profile.Pockets){Check(names.Add(pocket.Id),"unique pocket ID");float x=pocket.X*SpherePlacementRules.SourcePixelsToWorld,y=pocket.Y*SpherePlacementRules.SourcePixelsToWorld;Check(CampaignRegions.Nearest(profile.Region,x,y)==pocket,"simulation resolves authored pocket");var pool=new List<string>();for(int step=0;step<100;step++)foreach(float time in new[]{0f,900f,1500f}){var role=RegionPocketRules.SelectCampaignRole(profile.Region,x,y,step/100f,time);Check(validRoles.Contains(role),"all ecology roles have actual handlers");if(time==0&&step%25==0)pool.Add(role);}pools.Add(string.Join(",",pool));}Check(pools.Count>1,"pocket ecology changes real role composition");Check(validBosses.Contains(profile.FirstBoss)&&validBosses.Contains(profile.SecondBoss)&&validBosses.Contains(profile.FinalBoss),"profile references implemented bosses");}
 Console.WriteLine("Campaign regions: "+checks+" checks PASS");return checks;}
}
